local MournBuffDisplayRightNode = Class('MournBuffDisplayRightNode')
---@type ActivityMournUtils
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournBuffDisplayRightNode:__init()
	self._buffId = nil
	self._cb = nil

end

function MournBuffDisplayRightNode:__delete()
	self._buffId = nil
	self._cb = nil

end

function MournBuffDisplayRightNode:Awake()
	SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnUpLevel))
	SetButtonAction(self.FontStyleButton2, Bind(self, self.OnBtnRemove))
	SetButtonAction(self.FontStyleButton3, Bind(self, self.OnBtnEquip))
end

---Refresh
---@param data table
function MournBuffDisplayRightNode:Refresh(buffId, cb)
	if not buffId then
		return
	end
	self._buffId = buffId
	self._cb = cb
	
	self:FillSelf()
end

function MournBuffDisplayRightNode:FillSelf()
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting6609, "NightCatGoodsVo", self._buffId)
	if not vo then
		return
	end
	
	local isUnlock = ActivityMournUtils.IsUnLockBuff(self._buffId)
	local isEquip = ActivityMournUtils.IsEquipBuff(self._buffId)
	
	CfUtils.SetActive(self.StatusNotGet, not isUnlock)
	CfUtils.SetActive(self.StatusHasGet, isUnlock)
	
	CfUtils.SetActive(self.UnlockMethodNode, not isUnlock)
	CfUtils.SetActive(self.BtnNode, isUnlock)
	
	CfUtils.FillText(self.TextName, vo.name)
	CfUtils.FillText(self.TextDesc2, vo.description)
	CfUtils.SetActive(self.TextDesc2, isUnlock)
	
	CfUtils.SetActive(self.TextDesc1, true)
	
	if isUnlock then
		local isMaxLevel = ActivityMournUtils.IsBuffMaxLevel(self._buffId)
		local level = ActivityMournUtils.GetBuffLevel(self._buffId)
		
		--满级
		if isMaxLevel then
			CfUtils.FillText(self.TextLevel, "MAX")
		else
			CfUtils.FillText(self.TextLevel, "Lv."..level)
			local t = ActivityMournUtils.GetMournBuffUpLevelConsume(self._buffId,level + 1)  --QuestConfMgr:GetInstance():GetNightCatBuffUpLevelConsume(self._buffId, level + 1)
			if t then
				CfUtils.FillImage(self.Image, GoodsConfMgr:GetInstance():GetPhotoPathById(t.goodsId))
				CfUtils.FillText(self.Text2, "x"..t.num)
			end
		end
		
		CfUtils.FillImage(self.ImgIcon, vo.photoId)
		CfUtils.FillImage(self.ImgIcon2, vo.photoId)
		CfUtils.SetActive(self.StatusEquip, isEquip)
		
		CfUtils.SetActive(self.FontStyleButton3, not isEquip)
		CfUtils.SetActive(self.FontStyleButton2, isEquip)
		CfUtils.SetActive(self.UngradeNode, not isMaxLevel)
	
		local effectVo = ActivityMournUtils.GetBuffEffectVo(self._buffId, level)
		CfUtils.FillText(self.TextDesc1, effectVo.desc)
		
		local questUpBuffVo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(self._buffId..level) or {}
		CfUtils.FillText(self.TextNumber, string.fmt('+%1', checkInt(questUpBuffVo.combatValue1)))
	else
		local effectVo = ActivityMournUtils.GetBuffEffectVo(self._buffId, 1)
		CfUtils.FillText(self.TextDesc1, effectVo.desc)
		CfUtils.FillText(self.TextNumber, '')
		
		local plotVo = CfUtils.GetCfVo(AutoIds.IdSetting6611, "MournPlotVo", vo.plotId) --QuestConfMgr:GetInstance():GetNightCatPlotVo(vo.plotId)
		if plotVo then
			CfUtils.FillText(self.Text, plotVo.buffUnlockTips)
		end
	end
end

--升级
function MournBuffDisplayRightNode:OnBtnUpLevel()
	local isEnd = ActivityMournUtils.IsActivityEnd(true)
	if isEnd then
		return
	end
	
	local isUnlock = ActivityMournUtils.IsUnLockBuff(self._buffId)
	if not isUnlock then
		return
	end
	local isMaxLevel = ActivityMournUtils.IsBuffMaxLevel(self._buffId)
	if isMaxLevel then
		GameUtils.Toast(localize("已到达最大等级"))
		return
	end
	
	local level = ActivityMournUtils.GetBuffLevel(self._buffId)
	local t = ActivityMournUtils.GetMournBuffUpLevelConsume(self._buffId,level + 1)
	if checkNumber(t.num) > GoodsUtils.GetThingNo(t.goodsId) then
		local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(t.goodsId)
		GameUtils.Toast(localize("_name_道具不足", {_name_ = vo.name}))
		return
	end
	
	local activityData = ActivityMournUtils.GetActivityData()
	GameUtils.Request(Interfaces.ActivityTowerChangeTowerGainUp, {activityUuid = activityData.id, goodsId = self._buffId}, function(request, response)
		if checkNumber(response.errCode) ~= 0 then
			return
		end
		local jsonData = response.data
		ActivityMournUtils.UpdateHaveBuffLevels(self._buffId, jsonData.newLevel)
		
		GoodsUtils.DrawRewards({{
									goodsId = t.goodsId,
									num = t.num * -1
								}}, true)
		
		self:FillSelf()
		
		CfUtils.PlayAnimation(self.BuffDisplayNode, "NightCatInstanceBuffDisplayDialogBubbleRightUp")
		if self._cb then
			self._cb()
		end
	end)
end

--卸下
function MournBuffDisplayRightNode:OnBtnRemove()
	local activityData = ActivityMournUtils.GetActivityData()
	GameUtils.Request(Interfaces.ActivityTowerChangeTowerGainChange,{activityUuid = activityData.id, type = 1, goodsId = self._buffId},function(request,response)
		if checkNumber(response.errCode) == 0 then
			local jsonData = response.data
			ActivityMournUtils.UpdateAssembleBuffIds(checkTable(jsonData.climbingInfo.climbingAssembleBuffIds))
			self:FillSelf()
			if self._cb then
				self._cb(false)
			end
		end
	end)
end

--装备
function MournBuffDisplayRightNode:OnBtnEquip()
	local t = ActivityMournUtils.GetEquipBuffIds()
	local count = 0
	for k, v in pairs(t) do
		if checkNumber(v) > 0 then
			count= count + 1
		end
	end
	
	if count >= ActivityMournUtils.GetMaxEquipBuffNum() then
		GameUtils.Toast(localize("装备位置已满"))
		return
	end
	
	local activityData = ActivityMournUtils.GetActivityData()
	GameUtils.Request(Interfaces.ActivityTowerChangeTowerGainChange,{activityUuid = activityData.id, type = 2, goodsId = self._buffId},function(request,response)
		if checkNumber(response.errCode) == 0 then
			local jsonData = response.data
			ActivityMournUtils.UpdateAssembleBuffIds(checkTable(jsonData.climbingInfo.climbingAssembleBuffIds))
			self:FillSelf()
			if self._cb then
				self._cb(true)
			end
		end
	end)
end

function MournBuffDisplayRightNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
	self = nil
end

return MournBuffDisplayRightNode